NO_FILL = set()  # icons whose open strokes would fill into odd shapes (set after looking at every icon on one sheet)


def _area(d):
    """A subpath that encloses an area and gets the duotone fill: three or more segments (Tabler leaves many outlines
    open by a hair); a two-point line or a dot never does."""
    return len(re.findall(r"[a-zA-Z]", d)) >= 4


def _markup(name, ds):
    """(fill path, stroke path): each icon's subpaths joined into ONE path. A gradient stroke on a lone straight line has a
    zero-width bounding box and is not painted at all; on the whole icon it is, and the draw-on still runs (the dash
    pattern continues from subpath to subpath)."""
    fill = " ".join(d for d in ds if _area(d)) if name not in NO_FILL else ""
    return fill, " ".join(ds)


ICONS = {name: _markup(name, ds) for name, (_, ds) in SOURCE.items()}


def icon(name, size=120, grad="url(#lg)", width=4, extra=""):
    """An icon at size px in the colour or gradient grad. width is the old 120-unit stroke width (4-6), drawn about 1.6×
    heavier on the 24-unit Tabler grid than the former hand-drawn set, so the icons read at a glance."""
    fill, line = ICONS.get(name, ICONS["spark"])
    sw = max(1.4, width * 0.34)
    under = f'<path class="icf" d="{fill}" fill="{grad}" stroke="none" fill-opacity="0.2" />' if fill else ""
    return (f'<svg width="{size}" height="{size}" viewBox="0 0 24 24" fill="none" stroke="{grad}" stroke-width="{sw:.2f}" '
            f'stroke-linecap="round" stroke-linejoin="round" {extra}>{under}<path class="ic" pathLength="1" d="{line}" /></svg>')
